(6743624, 1009157, 142473, '<td valign="top">Ouch.  What a perfectly timed shot.  What a painful looking image.  Were the rider and horse ok!?</td>', 'Ouch.  What a perfectly timed shot.  What a painful looking image.  Were the rider and horse ok!?', '2012-04-16 17:00:43.000000', NULL, 1),
(6743625, 1008724, 142473, '<td valign="top">Great templistic structure, and a solid image.  Though, I''m not a huge fan of the anti-vignette at the bottom left and right.</td>', 'Great templistic structure, and a solid image.  Though, I''m not a huge fan of the anti-vignette at the bottom left and right.', '2012-04-16 17:01:38.000000', NULL, 1),
