(6744672, 1009094, 120171, '<td valign="top">Having the horizon run across the centre of the frame along with the blown out sky are hurting your image.<br/>I like the use of the path as a leading line.</td>', 'Having the horizon run across the centre of the frame along with the blown out sky are hurting your image.I like the use of the path as a leading line.', '2012-04-17 18:06:25.000000', NULL, 1),
(6744674, 1008748, 120171, '<td valign="top">The riders in the foreground look really distorted as if the clarity has been ramped up. For me the riders are a distraction as opposed to a compliment of the image.</td>', 'The riders in the foreground look really distorted as if the clarity has been ramped up. For me the riders are a distraction as opposed to a compliment of the image.', '2012-04-17 18:09:23.000000', NULL, 1),
(6744676, 1009199, 120171, '<td valign="top">I like the composition and the colours the HDR has brought to the image but you have significant haloing around the trees as a result.</td>', 'I like the composition and the colours the HDR has brought to the image but you have significant haloing around the trees as a result.', '2012-04-17 18:10:59.000000', NULL, 1),
(6744680, 1009343, 120171, '<td valign="top">Great contrast and flare.</td>', 'Great contrast and flare.', '2012-04-17 18:14:56.000000', NULL, 1),
(6744681, 1009157, 120171, '<td valign="top">Ouch thats gotta hurt. Great action shot.</td>', 'Ouch thats gotta hurt. Great action shot.', '2012-04-17 18:19:27.000000', NULL, 1),
(6744683, 1009290, 120171, '<td valign="top">I like the landscape but you have a lot of dust spots in your sky.</td>', 'I like the landscape but you have a lot of dust spots in your sky.', '2012-04-17 18:21:19.000000', NULL, 1),
(6744685, 1008821, 120171, '<td valign="top">I think you may have pushed the PP a bit too far as there are a lot of halos. If it was intentional IMO it doesn''t work. <br/>The scene it''s self is very nice and would have looked good without the PP.</td>', 'I think you may have pushed the PP a bit too far as there are a lot of halos. If it was intentional IMO it doesn''t work. The scene it''s self is very nice and would have looked good without the PP.', '2012-04-17 18:25:49.000000', NULL, 1),
(6744689, 1009208, 120171, '<td valign="top">Oh why didn''t i think of that. Excellent and should be on the front in the morning. 10</td>', 'Oh why didn''t i think of that. Excellent and should be on the front in the morning. 10', '2012-04-17 18:38:42.000000', NULL, 1),
(6744690, 1008759, 120171, '<td valign="top">But where does it lead. I will be surprised if you don''t receive a ribbon. 10</td>', 'But where does it lead. I will be surprised if you don''t receive a ribbon. 10', '2012-04-17 18:39:58.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6744691, 1009104, 120171, '<td valign="top">The male looks almost Monarch like sitting on his thrown, whilst the lady looks on in terror. Wow so many stories are buzzing around my head as to what the actual story is about.<br/>In a nutshell your image got me, I''m hooked.</td>', 'The male looks almost Monarch like sitting on his thrown, whilst the lady looks on in terror. Wow so many stories are buzzing around my head as to what the actual story is about.In a nutshell your image got me, I''m hooked.', '2012-04-17 18:40:35.000000', NULL, 1),
(6744692, 1009345, 120171, '<td valign="top">I rwally like the deep shadows throughout your image. Nice work.</td>', 'I rwally like the deep shadows throughout your image. Nice work.', '2012-04-17 18:41:11.000000', NULL, 1),
(6744721, 1009305, 38725, '<td valign="top">Beautiful abstract.</td>', 'Beautiful abstract.', '2012-04-17 20:08:53.000000', NULL, 1),
(6744722, 1009305, 97225, '<td valign="top">Lovely abstract, colours are beautiful.</td>', 'Lovely abstract, colours are beautiful.', '2012-04-17 20:08:59.000000', NULL, 1),
(6744724, 1008648, 38725, '<td valign="top">Nice leading lines, would have liked to see it from the other end though eg, leading to the end of the line rather than starting there.</td>', 'Nice leading lines, would have liked to see it from the other end though eg, leading to the end of the line rather than starting there.', '2012-04-17 20:09:40.000000', NULL, 1),
(6744726, 1009191, 38725, '<td valign="top">Great sunset, not sure I like the darkness below it though.</td>', 'Great sunset, not sure I like the darkness below it though.', '2012-04-17 20:10:12.000000', NULL, 1),
(6744728, 1008436, 97225, '<td valign="top">An incredible find, indeed! <br/>This is really quite a brilliant setting for a fairytale/fantasy. The shape of the hollow in the tree trunk looks like the magical birthplace of a woodland nymph.</td>', 'An incredible find, indeed! This is really quite a brilliant setting for a fairytale/fantasy. The shape of the hollow in the tree trunk looks like the magical birthplace of a woodland nymph.', '2012-04-17 20:11:26.000000', NULL, 1),
(6744729, 1009328, 3102, '<td valign="top">Wow... beautiful scene!</td>', 'Wow... beautiful scene!', '2012-04-17 20:12:16.000000', NULL, 1),
(6744730, 1009257, 97225, '<td valign="top">Beautiful place, wonderful sky.</td>', 'Beautiful place, wonderful sky.', '2012-04-17 20:12:34.000000', NULL, 1),
(6744731, 1008588, 38725, '<td valign="top">I like the softness.</td>', 'I like the softness.', '2012-04-17 20:12:36.000000', NULL, 1),
(6744733, 1009233, 97225, '<td valign="top">Delightful setting.</td>', 'Delightful setting.', '2012-04-17 20:13:05.000000', NULL, 1),
(6744735, 1008819, 38725, '<td valign="top">Nice idea, lovely shot with great colour.</td>', 'Nice idea, lovely shot with great colour.', '2012-04-17 20:13:13.000000', NULL, 1),
(6744736, 1009186, 97225, '<td valign="top">This makes me think that the lizard is about to enter the mouth of some sort of ogre or giant.</td>', 'This makes me think that the lizard is about to enter the mouth of some sort of ogre or giant.', '2012-04-17 20:14:09.000000', NULL, 1),
(6744737, 1008819, 3102, '<td valign="top">Cool that you were able to get it without people in it!  When I was there, that wasn''t a possibility.  I still envision Jin &amp; Sun''s wedding (Lost) when I see this place :)</td>', 'Cool that you were able to get it without people in it!  When I was there, that wasn''t a possibility.  I still envision Jin & Sun''s wedding (Lost) when I see this place :)', '2012-04-17 20:14:19.000000', NULL, 1),
(6744739, 1009173, 97225, '<td valign="top">Lovely place to go riding. I want to get on a bike and join them.</td>', 'Lovely place to go riding. I want to get on a bike and join them.', '2012-04-17 20:14:51.000000', NULL, 1),
(6744740, 1008316, 38725, '<td valign="top">I don''t want to know how they got that car into that position, well actually I do... Interesting capture ;)</td>', 'I don''t want to know how they got that car into that position, well actually I do... Interesting capture ;)', '2012-04-17 20:15:00.000000', NULL, 1),
(6744741, 1009199, 103142, '<td valign="top">Nice shot, but you have some pretty bad haloing going on around the trees.</td>', 'Nice shot, but you have some pretty bad haloing going on around the trees.', '2012-04-17 20:15:03.000000', NULL, 1),
(6744742, 1009105, 97225, '<td valign="top">Lovely. I love the leading lines and the scenery is beautiful.</td>', 'Lovely. I love the leading lines and the scenery is beautiful.', '2012-04-17 20:15:41.000000', NULL, 1),
(6744744, 1009211, 103142, '<td valign="top">I can''t tell whether or not I like the subjects at the extreme ends of the picture or not... part of the time I''m thinking it''s interesting, and part not. I''m curious what a lower perspective would look like.</td>', 'I can''t tell whether or not I like the subjects at the extreme ends of the picture or not... part of the time I''m thinking it''s interesting, and part not. I''m curious what a lower perspective would look like.', '2012-04-17 20:16:35.000000', NULL, 1),
(6744746, 1008316, 97225, '<td valign="top">Oh, wow! Looks like they could be there for weeks. They look remarkably cheerful about it.</td>', 'Oh, wow! Looks like they could be there for weeks. They look remarkably cheerful about it.', '2012-04-17 20:17:22.000000', NULL, 1),
(6744747, 1009186, 103142, '<td valign="top">haha! My first thought is that it''s DNMC. But what the heck -- why can''t it be a lizard road!<br/> <br/>Ok. It works for me. 7</td>', 'haha! My first thought is that it''s DNMC. But what the heck -- why can''t it be a lizard road! Ok. It works for me. 7', '2012-04-17 20:17:27.000000', NULL, 1),
(6744749, 1009179, 97225, '<td valign="top">Magnificent view!</td>', 'Magnificent view!', '2012-04-17 20:18:00.000000', NULL, 1),
(6744750, 1009208, 38725, '<td valign="top">Really nice shot, great idea, if I had to find something to be critical about (and there isn''t much really) it would be the perspective, perhaps taken a little more from the left so it looks like the view is from a car would be good. Just IMHO ;)</td>', 'Really nice shot, great idea, if I had to find something to be critical about (and there isn''t much really) it would be the perspective, perhaps taken a little more from the left so it looks like the view is from a car would be good. Just IMHO ;)', '2012-04-17 20:18:00.000000', NULL, 1),
(6744751, 1009141, 103142, '<td valign="top">Interesting idea. But you need to think larger. My perfect world is much more than recycling. :)</td>', 'Interesting idea. But you need to think larger. My perfect world is much more than recycling. :)', '2012-04-17 20:18:06.000000', NULL, 1),
(6744753, 1009113, 38725, '<td valign="top">A bit gruesome, interesting message though, like it a lot.</td>', 'A bit gruesome, interesting message though, like it a lot.', '2012-04-17 20:19:08.000000', NULL, 1),
(6744754, 1009157, 38725, '<td valign="top">Ouch, you definitely pressed the shutter at just the right (or wrong for the girl and horse) moment.</td>', 'Ouch, you definitely pressed the shutter at just the right (or wrong for the girl and horse) moment.', '2012-04-17 20:20:15.000000', NULL, 1),
(6744757, 1008738, 103142, '<td valign="top">Don''t know what to do with this one. It seems like DNMC, and yet it''s not...<br/> <br/>Ok -- the more I think about it, it definitely fits (or I''ve just made it fit. :)<br/> <br/>Which is good, because I like the shot. Although it looks like you have haloing going on around the handlebars.</td>', 'Don''t know what to do with this one. It seems like DNMC, and yet it''s not... Ok -- the more I think about it, it definitely fits (or I''ve just made it fit. :) Which is good, because I like the shot. Although it looks like you have haloing going on around the handlebars.', '2012-04-17 20:20:58.000000', NULL, 1),
(6744758, 1009268, 38725, '<td valign="top">Would have liked more DoF for this shot.</td>', 'Would have liked more DoF for this shot.', '2012-04-17 20:21:21.000000', NULL, 1),
(6744759, 1008648, 103142, '<td valign="top">I wish there was a little more to the processing on this. I like the composition and the idea, but it just seems a bit flat, imo.</td>', 'I wish there was a little more to the processing on this. I like the composition and the idea, but it just seems a bit flat, imo.', '2012-04-17 20:22:06.000000', NULL, 1),
(6744760, 1009157, 103142, '<td valign="top">ouch!! I hope it''s not really the end of the road. :)</td>', 'ouch!! I hope it''s not really the end of the road. :)', '2012-04-17 20:22:32.000000', NULL, 1),
(6744762, 1009163, 38725, '<td valign="top">Dark and moody, I like it :)</td>', 'Dark and moody, I like it :)', '2012-04-17 20:22:58.000000', NULL, 1),
(6744763, 1009309, 103142, '<td valign="top">This is really quite cool. I almost wish the part in the upper left wasn''t there. The rest is so mysterious, and I find it a bit intrusive. Yet it''s interesting as well...</td>', 'This is really quite cool. I almost wish the part in the upper left wasn''t there. The rest is so mysterious, and I find it a bit intrusive. Yet it''s interesting as well...', '2012-04-17 20:23:25.000000', NULL, 1),
(6744764, 1009214, 103142, '<td valign="top">I like the idea, I like the photo, the processing seems a little flat. I wonder what this would look like in a gritty b&amp;w</td>', 'I like the idea, I like the photo, the processing seems a little flat. I wonder what this would look like in a gritty b&w', '2012-04-17 20:24:17.000000', NULL, 1),
(6744765, 1009290, 103142, '<td valign="top">Intriguing landscape.</td>', 'Intriguing landscape.', '2012-04-17 20:24:35.000000', NULL, 1),
(6744767, 1009328, 103142, '<td valign="top">wow... I wish my roads looked like this!</td>', 'wow... I wish my roads looked like this!', '2012-04-17 20:25:30.000000', NULL, 1),
(6744769, 1009120, 103142, '<td valign="top">Hmmm... interesting thought. I would have thought a way in would be at the end of the road. Finding the way out is an interesting concept.</td>', 'Hmmm... interesting thought. I would have thought a way in would be at the end of the road. Finding the way out is an interesting concept.', '2012-04-17 20:26:29.000000', NULL, 1),
